CREATE TABLE IF NOT EXISTS `site_settings` (`id` integer PRIMARY KEY NOT NULL, `artist_name` text NOT NULL, `subtitle` text DEFAULT '' NOT NULL, `bio` text DEFAULT '' NOT NULL, `portrait_path` text, `created_at` text NOT NULL, `updated_at` text NOT NULL);
CREATE TABLE IF NOT EXISTS `social_links` (`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL, `platform` text DEFAULT 'other' NOT NULL, `label` text NOT NULL, `url` text NOT NULL, `sort_order` integer DEFAULT 0 NOT NULL, `enabled` integer DEFAULT true NOT NULL);
CREATE TABLE IF NOT EXISTS `artworks` (`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL, `slug` text NOT NULL, `title` text NOT NULL, `year` integer NOT NULL, `medium` text NOT NULL, `type` text NOT NULL, `description` text, `media_path` text, `alt_text` text, `external_url` text, `source_url` text, `component_key` text, `dimensions` text, `duration` text, `edition` text, `file_size` text, `date_created` text, `software` text, `hardware` text, `programming_language` text, `autoplay` integer DEFAULT true NOT NULL, `muted` integer DEFAULT true NOT NULL, `loop` integer DEFAULT true NOT NULL, `controls` integer DEFAULT true NOT NULL, `sort_order` integer DEFAULT 0 NOT NULL, `status` text DEFAULT 'draft' NOT NULL, `created_at` text NOT NULL, `updated_at` text NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS `artworks_slug_unique` ON `artworks` (`slug`);
CREATE TABLE IF NOT EXISTS `admin_users` (`id` integer PRIMARY KEY NOT NULL, `password_hash` text NOT NULL, `updated_at` text NOT NULL);
